-- Song Book Library - initial schema (PostgreSQL 16+)
-- Conventions: UUID PKs generated by the application (gen_random_uuid() as DB fallback),
-- TIMESTAMPTZ for instants, DATE for calendar dates, VARCHAR + CHECK for enums,
-- "version" columns for optimistic locking on concurrently edited rows.

-- ---------------------------------------------------------------------------
-- Users, roles, memberships
-- ---------------------------------------------------------------------------
CREATE TABLE users (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    full_name         VARCHAR(150) NOT NULL,
    email             VARCHAR(254) NOT NULL,
    password_hash     VARCHAR(255) NOT NULL,
    account_status    VARCHAR(20)  NOT NULL DEFAULT 'ACTIVE',
    email_verified    BOOLEAN      NOT NULL DEFAULT FALSE,
    email_verified_at TIMESTAMPTZ  NULL,
    failed_login_count INTEGER     NOT NULL DEFAULT 0,
    locked_until      TIMESTAMPTZ  NULL,
    created_at        TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ  NOT NULL DEFAULT now(),
    version           BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT uq_users_email UNIQUE (email),
    CONSTRAINT ck_users_email_normalized CHECK (email = lower(btrim(email))),
    CONSTRAINT ck_users_account_status CHECK (account_status IN ('ACTIVE', 'DISABLED', 'LOCKED')),
    CONSTRAINT ck_users_verified_at CHECK (email_verified = FALSE OR email_verified_at IS NOT NULL),
    CONSTRAINT ck_users_failed_login CHECK (failed_login_count >= 0)
);

CREATE TABLE roles (
    id   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name VARCHAR(30) NOT NULL,
    CONSTRAINT uq_roles_name UNIQUE (name),
    CONSTRAINT ck_roles_name CHECK (name IN ('MEMBER', 'ADMIN'))
);

INSERT INTO roles (name) VALUES ('MEMBER'), ('ADMIN');

CREATE TABLE user_roles (
    user_id UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role_id UUID NOT NULL REFERENCES roles (id) ON DELETE RESTRICT,
    PRIMARY KEY (user_id, role_id)
);
CREATE INDEX ix_user_roles_role ON user_roles (role_id);

-- Membership history is preserved: a user may have many rows, but at most one ACTIVE row.
CREATE TABLE memberships (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id    UUID        NOT NULL REFERENCES users (id) ON DELETE RESTRICT,
    start_date DATE        NOT NULL,
    end_date   DATE        NULL,
    status     VARCHAR(20) NOT NULL,
    notes      VARCHAR(500) NULL,
    created_by UUID        NULL REFERENCES users (id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    version    BIGINT      NOT NULL DEFAULT 0,
    CONSTRAINT ck_memberships_status CHECK (status IN ('ACTIVE', 'SUSPENDED', 'EXPIRED', 'CANCELLED')),
    CONSTRAINT ck_memberships_dates CHECK (end_date IS NULL OR end_date >= start_date)
);
CREATE INDEX ix_memberships_user ON memberships (user_id, status, start_date, end_date);
CREATE UNIQUE INDEX uq_memberships_one_active ON memberships (user_id) WHERE status = 'ACTIVE';

-- ---------------------------------------------------------------------------
-- Auth tokens (only SHA-256 hashes are stored, never raw tokens)
-- ---------------------------------------------------------------------------
CREATE TABLE user_tokens (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id     UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    purpose     VARCHAR(30) NOT NULL,
    token_hash  VARCHAR(64)    NOT NULL,
    expires_at  TIMESTAMPTZ NOT NULL,
    used_at     TIMESTAMPTZ NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_user_tokens_hash UNIQUE (token_hash),
    CONSTRAINT ck_user_tokens_purpose CHECK (purpose IN ('EMAIL_VERIFICATION', 'PASSWORD_RESET'))
);
CREATE INDEX ix_user_tokens_user ON user_tokens (user_id, purpose);

-- Refresh tokens rotate on each use; family_id allows revoking a whole chain on reuse detection.
CREATE TABLE refresh_tokens (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id      UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    family_id    UUID        NOT NULL,
    token_hash   VARCHAR(64)    NOT NULL,
    expires_at   TIMESTAMPTZ NOT NULL,
    revoked_at   TIMESTAMPTZ NULL,
    replaced_by  UUID        NULL REFERENCES refresh_tokens (id) ON DELETE SET NULL,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_refresh_tokens_hash UNIQUE (token_hash)
);
CREATE INDEX ix_refresh_tokens_user ON refresh_tokens (user_id);
CREATE INDEX ix_refresh_tokens_family ON refresh_tokens (family_id);

-- ---------------------------------------------------------------------------
-- Catalogue
-- ---------------------------------------------------------------------------
CREATE TABLE book_categories (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name        VARCHAR(100) NOT NULL,
    description TEXT         NULL,
    active      BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    version     BIGINT       NOT NULL DEFAULT 0
);
CREATE UNIQUE INDEX uq_book_categories_name ON book_categories (lower(name));

-- Metadata for files in Blob/local storage. Never holds SAS tokens or URLs.
CREATE TABLE file_assets (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    container_name    VARCHAR(63)  NOT NULL,
    blob_name         VARCHAR(512) NOT NULL,
    original_filename VARCHAR(255) NOT NULL,
    content_type      VARCHAR(100) NOT NULL,
    file_size         BIGINT       NOT NULL,
    checksum_sha256   VARCHAR(64)     NOT NULL,
    page_count        INTEGER      NULL,
    created_at        TIMESTAMPTZ  NOT NULL DEFAULT now(),
    created_by        UUID         NULL REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT uq_file_assets_location UNIQUE (container_name, blob_name),
    CONSTRAINT ck_file_assets_size CHECK (file_size > 0),
    CONSTRAINT ck_file_assets_pages CHECK (page_count IS NULL OR page_count > 0),
    CONSTRAINT ck_file_assets_content_type CHECK (
        content_type IN ('application/pdf', 'image/jpeg', 'image/png', 'image/webp'))
);

CREATE TABLE books (
    id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    title              VARCHAR(200) NOT NULL,
    description        TEXT         NULL,
    category_id        UUID         NULL REFERENCES book_categories (id) ON DELETE RESTRICT,
    cover_asset_id     UUID         NULL REFERENCES file_assets (id) ON DELETE RESTRICT,
    effective_date     DATE         NOT NULL,
    expiry_date        DATE         NULL,
    status             VARCHAR(20)  NOT NULL DEFAULT 'DRAFT',
    current_version_id UUID         NULL,
    uploaded_by        UUID         NULL REFERENCES users (id) ON DELETE SET NULL,
    created_at         TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ  NOT NULL DEFAULT now(),
    version            BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT ck_books_status CHECK (status IN ('DRAFT', 'PUBLISHED', 'INACTIVE', 'ARCHIVED')),
    CONSTRAINT ck_books_dates CHECK (expiry_date IS NULL OR expiry_date >= effective_date),
    CONSTRAINT ck_books_title CHECK (length(btrim(title)) > 0)
);
CREATE INDEX ix_books_catalogue ON books (status, effective_date, expiry_date);
CREATE INDEX ix_books_category ON books (category_id);
CREATE INDEX ix_books_title_lower ON books (lower(title));

CREATE TABLE book_versions (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    book_id        UUID        NOT NULL REFERENCES books (id) ON DELETE RESTRICT,
    version_number INTEGER     NOT NULL,
    pdf_asset_id   UUID        NOT NULL REFERENCES file_assets (id) ON DELETE RESTRICT,
    change_note    VARCHAR(500) NULL,
    uploaded_by    UUID        NULL REFERENCES users (id) ON DELETE SET NULL,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_book_versions_number UNIQUE (book_id, version_number),
    CONSTRAINT uq_book_versions_asset UNIQUE (pdf_asset_id),
    CONSTRAINT ck_book_versions_number CHECK (version_number > 0)
);

-- Circular reference added after both tables exist. The composite FK guarantees the
-- current version belongs to the same book.
ALTER TABLE book_versions ADD CONSTRAINT uq_book_versions_id_book UNIQUE (id, book_id);
ALTER TABLE books
    ADD CONSTRAINT fk_books_current_version
        FOREIGN KEY (current_version_id, id) REFERENCES book_versions (id, book_id)
        DEFERRABLE INITIALLY DEFERRED;
-- A published book must have a PDF.
ALTER TABLE books
    ADD CONSTRAINT ck_books_published_has_version
        CHECK (status <> 'PUBLISHED' OR current_version_id IS NOT NULL);

-- Blobs that may be orphaned (DB failure after upload, failed cleanup). Processed by a
-- reconciliation job; see docs/ARCHITECTURE.md "Storage consistency".
CREATE TABLE storage_cleanup_queue (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    container_name VARCHAR(63)  NOT NULL,
    blob_name      VARCHAR(512) NOT NULL,
    reason         VARCHAR(100) NOT NULL,
    attempts       INTEGER      NOT NULL DEFAULT 0,
    last_error     VARCHAR(1000) NULL,
    created_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    processed_at   TIMESTAMPTZ  NULL,
    CONSTRAINT ck_storage_cleanup_attempts CHECK (attempts >= 0)
);
CREATE INDEX ix_storage_cleanup_pending ON storage_cleanup_queue (created_at) WHERE processed_at IS NULL;

-- ---------------------------------------------------------------------------
-- Member activity
-- ---------------------------------------------------------------------------
CREATE TABLE reading_progress (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    book_id         UUID        NOT NULL REFERENCES books (id) ON DELETE CASCADE,
    book_version_id UUID        NULL REFERENCES book_versions (id) ON DELETE SET NULL,
    last_page       INTEGER     NOT NULL,
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_reading_progress_user_book UNIQUE (user_id, book_id),
    CONSTRAINT ck_reading_progress_page CHECK (last_page >= 1)
);
CREATE INDEX ix_reading_progress_user_recent ON reading_progress (user_id, updated_at DESC);

CREATE TABLE modification_requests (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    requested_by  UUID         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    book_id       UUID         NULL REFERENCES books (id) ON DELETE SET NULL,
    request_type  VARCHAR(30)  NOT NULL,
    description   TEXT         NOT NULL,
    status        VARCHAR(20)  NOT NULL DEFAULT 'PENDING',
    review_note   VARCHAR(1000) NULL,
    reviewed_by   UUID         NULL REFERENCES users (id) ON DELETE SET NULL,
    reviewed_at   TIMESTAMPTZ  NULL,
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    version       BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT ck_modreq_type CHECK (request_type IN ('CORRECTION', 'ADDITION', 'OTHER')),
    CONSTRAINT ck_modreq_status CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED')),
    CONSTRAINT ck_modreq_review CHECK (
        (status = 'PENDING' AND reviewed_at IS NULL) OR (status <> 'PENDING' AND reviewed_at IS NOT NULL)),
    CONSTRAINT ck_modreq_description CHECK (length(btrim(description)) > 0)
);
CREATE INDEX ix_modreq_status ON modification_requests (status, created_at);
CREATE INDEX ix_modreq_requester ON modification_requests (requested_by, created_at DESC);

-- Append-only. details must never contain passwords, tokens, SAS URLs or secrets.
CREATE TABLE audit_logs (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    actor_user_id UUID         NULL REFERENCES users (id) ON DELETE SET NULL,
    action        VARCHAR(60)  NOT NULL,
    entity_type   VARCHAR(60)  NOT NULL,
    entity_id     UUID         NULL,
    details       JSONB        NULL,
    ip_address    VARCHAR(45)  NULL,
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now()
);
CREATE INDEX ix_audit_created ON audit_logs (created_at DESC);
CREATE INDEX ix_audit_actor ON audit_logs (actor_user_id, created_at DESC);
CREATE INDEX ix_audit_entity ON audit_logs (entity_type, entity_id);
CREATE INDEX ix_audit_action ON audit_logs (action, created_at DESC);
